def define_schema(cls) -> io.Schema:
    return io.Schema(node_id='ChromaRadianceOptions', category='model_patches/chroma_radiance', description='Allows setting advanced options for the Chroma Radiance model.', inputs=[io.Model.Input(id='model'), io.Boolean.Input(id='preserve_wrapper', default=True, tooltip='When enabled, will delegate to an existing model function wrapper if it exists. Generally should be left enabled.'), io.Float.Input(id='start_sigma', default=1.0, min=0.0, max=1.0, tooltip='First sigma that these options will be in effect.'), io.Float.Input(id='end_sigma', default=0.0, min=0.0, max=1.0, tooltip='Last sigma that these options will be in effect.'), io.Int.Input(id='nerf_tile_size', default=-1, min=-1, tooltip='Allows overriding the default NeRF tile size. -1 means use the default (32). 0 means use non-tiling mode (may require a lot of VRAM).')], outputs=[io.Model.Output()])